<?php declare(strict_types=1);require __DIR__.'/../includes/bootstrap.php';require_admin();$q=trim((string)($_GET['q']??''));$s=db()->prepare('SELECT t.*,u.name user_name,c.name category FROM transactions t JOIN users u ON u.user_id=t.user_id JOIN categories c ON c.category_id=t.category_id WHERE t.status="active" AND (u.name LIKE ? OR t.description LIKE ? OR c.name LIKE ?) ORDER BY t.transaction_date DESC,t.transaction_id DESC LIMIT 500');$s->execute(["%$q%","%$q%","%$q%"]) ;$rows=$s->fetchAll();$pageTitle='Transactions';$activePage='transactions';require __DIR__.'/../includes/app_header.php';?><section class="page-head"><div><span class="eyebrow">GLOBAL LEDGER</span><h1>Transaction activity</h1><p>System-wide usage view for administration.</p></div></section><section class="panel"><form class="filter-bar"><input class="input" name="q" value="<?=e($q)?>" placeholder="Search student, category or description"><button class="btn btn-primary">Search</button></form></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>Date</th><th>Student</th><th>Description</th><th>Category</th><th>Type</th><th>Amount</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=e(date('d M Y',strtotime($r['transaction_date'])))?></td><td><?=e($r['user_name'])?></td><td><?=e($r['description'])?></td><td><?=e($r['category'])?></td><td><?=e($r['type'])?></td><td><?=money($r['amount'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/../includes/footer.php';?>